const {missions,sources,glossary}=window.ACADEMY;
const icons={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',
 identity:'<rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="9" cy="10" r="2"/><path d="M6 16c0-4 6-4 6 0m3-7h3m-3 4h3"/>',
 fingerprint:'<path d="M5 9a7 7 0 0 1 14 0m-17 4v-2a10 10 0 0 1 20 0v2M8 18c1-2 1-4 1-7a3 3 0 0 1 6 0c0 4 0 7 2 9M5 13c0 4-1 6-2 7m9-9c0 5 0 8-2 11m9-9c0 3 0 4 2 5"/>',
 door:'<path d="M4 21h16M7 21V4l10-2v19M17 5h3v16M13 12v2"/>',
 cycle:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',
 card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4m6 0h2"/>',
 laptop:'<rect x="5" y="3" width="14" height="13" rx="2"/><path d="m5 16-3 4h20l-3-4M9 20h6"/>',
 radar:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><path d="m12 12 7-7"/><circle cx="12" cy="12" r="1"/>',
 bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',
 book:'<path d="M12 5c-4-3-9-1-9-1v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1Zm0 0v15"/>',
 chart:'<path d="M4 3v17h17M8 16v-4m5 4V8m5 8V5"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
 trophy:'<path d="M7 3h10v6a5 5 0 0 1-10 0zm0 2H3v2a5 5 0 0 0 5 5m9-7h4v2a5 5 0 0 1-5 5m-4 2v6m-5 1h10"/>',
 external:'<path d="M14 3h7v7m0-7-11 11M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>'
};
const icon=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.shield}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const main=document.querySelector('main');
const key='idex-academy-v1';
const questionIds=new Set(missions.flatMap(m=>m.questions.map(q=>q.id)));
let storageAvailable=true;
let state={answers:{},challenge:null,lastMission:null};
try{
 const old=JSON.parse(localStorage.getItem(key)||'null');
 if(old&&typeof old==='object'){
  for(const [id,a] of Object.entries(old.answers||{})) if(questionIds.has(id)&&a&&typeof a==='object') state.answers[id]={attempts:Math.max(0,Math.min(1000,Number(a.attempts)||0)),mastered:a.mastered===true,xp:a.mastered===true?(a.xp===100?100:60):0};
  if(old.challenge&&Number.isInteger(old.challenge.score)&&old.challenge.score>=0&&old.challenge.score<=6)state.challenge={score:old.challenge.score,date:typeof old.challenge.date==='string'?old.challenge.date.slice(0,10):''};
  state.lastMission=missions.some(m=>m.id===old.lastMission)?old.lastMission:null;
 }
 localStorage.setItem(key,JSON.stringify(state));
}catch{storageAvailable=false;}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{storageAvailable=false;}updateHeader();}
const completed=m=>m.questions.every(q=>state.answers[q.id]?.mastered);
const completedCount=()=>missions.filter(completed).length;
const totalXP=()=>Object.values(state.answers).reduce((s,a)=>s+(a.xp||0),0);
const pct=()=>Math.round(Object.values(state.answers).filter(a=>a.mastered).length/24*100);
function rank(){return totalXP()>=1800?'Trust builder':totalXP()>=900?'Identity defender':totalXP()>=300?'Security explorer':'Curious defender';}
function nextMission(){return missions.find(m=>!completed(m))||missions[0];}
function sourceLink(id){const s=sources[id];return `<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('book')}${s.name}${icon('external')}</a>`;}
function updateHeader(){document.querySelector('#header-xp').textContent=`${totalXP().toLocaleString('en')} XP`;document.querySelector('.local-indicator').innerHTML=`<i></i>${storageAvailable?'Progress saved on this browser':'Storage unavailable · session only'}`;}
let quiz=null;
let lab={mode:'digital',match:true,site:true,active:true,rights:true,verified:true};
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),2600);}
function go(hash){location.hash=hash;}
function pageHead(eyebrow,title,sub){return `<div class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${sub}</p></div>`;}
function render(){
 const route=location.hash.slice(1)||'path';const tab=route.startsWith('mission/')?'path':route;
 document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===tab);if(a.dataset.nav===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.querySelector('#crumb').textContent=route.startsWith('mission/')?'Mission':({path:'Learning path',lab:'Card lab',challenge:'Final challenge',guide:'Field guide',progress:'My progress'}[tab]||'Learning path');
 if(route.startsWith('mission/')){
  const m=missions.find(m=>m.id===route.split('/')[1]);
  if(!m){go('path');return;}
  if(!quiz||quiz.mode!=='mission'||quiz.mission.id!==m.id){quiz={mode:'mission',mission:m,index:Math.max(0,m.questions.findIndex(q=>!state.answers[q.id]?.mastered)),selected:null};state.lastMission=m.id;save();}
  renderQuiz();
 }else{
  if(tab!=='challenge')quiz=null;
  if(tab==='path')renderPath();else if(tab==='lab')renderLab();else if(tab==='guide')renderGuide();else if(tab==='progress')renderProgress();else if(tab==='challenge'){if(quiz?.mode==='challenge')renderQuiz();else renderChallenge();}else renderPath();
 }
 updateHeader();
}
function renderPath(){
 const next=nextMission();const done=completedCount();
 main.innerHTML=`<section class="intro-row"><div><span class="eyebrow">BUILT FOR THE PEOPLE BEHIND IDEX</span><h1>Security is a skill.<br>Make it your instinct.</h1><p>Understand what we protect. Know how our technology works.<br class="desktop-br"> Make the right call when it counts.</p></div><span class="edition">SECURITY ESSENTIALS <b>101</b></span></section>
 <section class="hero"><div class="hero-copy"><span class="hero-tag"><i></i> YOUR NEXT MISSION</span><h2>${done===8?'Keep your security instincts sharp.':'Small decisions.<br>Stronger identity.'}</h2><p>${done===8?'You have completed the learning path. Take the final challenge or practise a mission again.':`Start with “${next.title}”. Three real-world decisions. One stronger security habit.`}</p><button class="button primary" data-action="start" data-id="${next.id}">${done===8?'Revisit a mission':Object.keys(state.answers).length?'Continue learning':'Start your first mission'}${icon('arrow')}</button><div class="hero-meta"><span>${icon('clock')}~24 min total</span><span>${icon('grid')}8 short missions</span><span>${icon('bolt')}Learn by doing</span></div></div>
 <div class="hero-art" aria-hidden="true"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="floating-note note-top">IDENTITY VERIFIED ${icon('check')}</div><div class="biometric-card"><div class="art-brand">IDEX<span>BIOMETRICS</span></div><div class="card-chip"><i></i><i></i><i></i></div><div class="card-fingerprint">${icon('fingerprint')}</div><div class="card-bottom"><span>TOTAL ACCESS<small>YOUR IDENTITY. YOURS.</small></span>${icon('shield')}</div></div><div class="floating-note note-bottom">${icon('lock')}Fingerprint stays on the card</div></div></section>
 <section class="stats-strip" aria-label="Your learning statistics"><div><span class="stat-icon">${icon('chart')}</span><span><strong>${done}<small> / 8</small></strong><span>Missions complete</span></span></div><div><span class="stat-icon gold">${icon('bolt')}</span><span><strong>${totalXP().toLocaleString('en')}<small> XP</small></strong><span>Experience earned</span></span></div><div><span class="stat-icon lavender">${icon('shield')}</span><span><strong class="rank-text">${rank()}</strong><span>Your current rank</span></span></div><div class="overall"><div><span>Learning path</span><b>${pct()}%</b></div><div class="progress-track"><span style="width:${pct()}%"></span></div></div></section>
 <section class="missions-section"><div class="section-title"><div><span class="eyebrow">THE LEARNING PATH</span><h2>Build your security instincts</h2></div><span class="section-hint">Choose a mission. Learn at your pace.</span></div><div class="mission-grid">${missions.map((m,i)=>{
  const n=m.questions.filter(q=>state.answers[q.id]?.mastered).length;const isDone=completed(m);return `<button class="mission-card ${isDone?'complete':''}" data-action="start" data-id="${m.id}"><div class="mission-top"><span class="mission-icon color-${i%4}">${icon(m.icon)}</span><span class="mission-status">${isDone?`${icon('check')} COMPLETED`:`MISSION ${String(i+1).padStart(2,'0')}`}</span></div><span class="mission-category">${m.category}</span><h3>${m.title}</h3><p>${m.description}</p><div class="mission-foot"><span>${icon('clock')}${m.minutes} min <i>·</i> ${n?n+'/3 learned':'3 decisions'}</span><span class="round-arrow">${icon(isDone?'check':'arrow')}</span></div>${n>0?`<div class="mission-progress"><span style="width:${n/3*100}%"></span></div>`:''}</button>`;
 }).join('')}</div></section>
 <section class="bottom-callout"><span class="callout-icon">${icon('fingerprint')}</span><div><span class="eyebrow">LESS THEORY. MORE “AHA”.</span><h3>What actually happens when you tap?</h3><p>Change the conditions in the card lab and see where trust holds, or breaks.</p></div><a class="button ghost" href="#lab">Explore the card lab ${icon('arrow')}</a></section>`;
}
function renderQuiz(){
 const isChallenge=quiz.mode==='challenge';const m=quiz.mission;const list=isChallenge?quiz.questions:m.questions;const q=list[quiz.index];
 if(!q){if(isChallenge)finishChallenge();else renderMissionComplete();return;}
 const selected=quiz.selected;const answered=selected!==null;const correct=selected===q.correct;
 const praise=isChallenge?'Good decision.':quiz.awarded?`Lesson learned. +${quiz.awarded} XP`:'Good decision. XP already earned.';
 main.innerHTML=`<div class="quiz-top"><a href="${isChallenge?'#challenge':'#path'}" ${isChallenge?'data-action="exit-challenge"':''} class="back-link">← ${isChallenge?'Exit challenge':'Learning path'}</a><span>${isChallenge?'FINAL CHALLENGE':m.category}</span><span>Decision ${quiz.index+1} of ${list.length}</span></div><div class="quiz-progress">${list.map((_,i)=>`<span class="${i<quiz.index?'done':i===quiz.index?'current':''}"></span>`).join('')}</div>
 <div class="quiz-layout"><section class="decision-panel"><div class="scenario-label">${icon(isChallenge?'bolt':m.icon)}<span>${q.scene}</span></div><h1>${q.prompt}</h1><p class="choose-label">Choose the best response.</p><div class="answers">${q.options.map((o,i)=>`<button class="answer ${selected===i?(correct?'correct':'incorrect'):''} ${isChallenge&&answered&&i===q.correct?'correct':''}" data-action="answer" data-index="${i}" ${answered?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${o}</span>${answered&&i===selected?icon(correct?'check':'close'):''}</button>`).join('')}</div>
 ${answered?`<div class="feedback ${correct?'positive':'negative'}" role="status"><div class="feedback-title">${icon(correct?'check':'radar')}<strong>${correct?praise:'A useful moment to learn.'}</strong></div><p>${correct||isChallenge?q.why:q.trap}</p>${sourceLink(q.source)}</div><button class="button ${correct||isChallenge?'primary':'ghost'} next-button" data-action="${correct||isChallenge?'next':'retry'}">${correct||isChallenge?(quiz.index===list.length-1?'See your result':'Next decision'):'Try another answer'}${icon('arrow')}</button>`:`<p class="quiet-hint">${isChallenge?'One answer per decision. Aim for 5 out of 6.':'No timer. Learn from every attempt. Your progress saves automatically.'}</p>`}</section>
 <aside class="lesson-panel"><span class="eyebrow">${isChallenge?'YOUR FIELD TEST':'THE IDEA TO REMEMBER'}</span><div class="lesson-symbol">${icon(isChallenge?'shield':m.icon)}</div><h2>${isChallenge?'Trust your training.':m.title}</h2><p>${isChallenge?'Six decisions across identity, the card, phishing, physical access, lifecycle and everyday security. Use what you have learned.':m.lesson}</p><div class="lesson-divider"></div><span class="eyebrow">${isChallenge?'THE GOAL':'WHY IT MATTERS AT IDEX'}</span><p>${isChallenge?'A learning badge recognises this practice result. It is not a professional certification.':m.takeaway}</p><div class="tiny-note">All people and situations in the missions are fictional.</div></aside></div>`;
}
function chooseAnswer(i){
 if(!quiz||quiz.selected!==null)return;
 const q=(quiz.mode==='challenge'?quiz.questions:quiz.mission.questions)[quiz.index];if(!q||i<0||i>=q.options.length)return;
 quiz.selected=i;quiz.awarded=0;
 if(quiz.mode==='challenge')quiz.results.push(i===q.correct);
 else if(!state.answers[q.id]?.mastered){const a=state.answers[q.id]||{attempts:0,mastered:false,xp:0};a.attempts++;if(i===q.correct){a.mastered=true;a.xp=a.attempts===1?100:60;quiz.awarded=a.xp;}state.answers[q.id]=a;save();}
 renderQuiz();
}
function renderMissionComplete(){
 const m=quiz.mission;const next=nextMission();const xp=m.questions.reduce((s,q)=>s+(state.answers[q.id]?.xp||0),0);
 main.innerHTML=`<section class="completion"><div class="completion-emblem">${icon(m.icon)}</div><span class="eyebrow">MISSION COMPLETE</span><h1>One stronger security instinct.</h1><p>You completed “${m.title}”.</p><div class="takeaway"><span class="eyebrow">TAKE THIS WITH YOU</span><h2>${m.takeaway}</h2></div><div class="result-chips"><span>${icon('check')}3 decisions learned</span><span>${icon('bolt')}${xp} XP earned in this mission</span></div><div class="button-row">${completedCount()<8?`<button class="button primary" data-action="start" data-id="${next.id}">Next mission ${icon('arrow')}</button>`:'<a class="button primary" href="#challenge">Take the final challenge '+icon('arrow')+'</a>'}<a class="button ghost" href="#path">Back to learning path</a></div><div class="completion-sources">${m.sources.map(sourceLink).join('')}</div></section>`;
}
function renderChallenge(){
 main.innerHTML=pageHead('PUT IT ALL TOGETHER','The trust challenge.','Six situations. One chance to respond to each. No countdown.')+`<section class="challenge-hero"><div class="challenge-crest">${icon('trophy')}</div><div><span class="eyebrow">YOUR FINAL FIELD TEST</span><h2>Can you make the right call?</h2><p>Apply your judgement across the product and the everyday risks around it. Get at least 5 of 6 decisions right to earn the Trust Champion learning badge.</p><div class="challenge-meta"><span>${icon('clock')}~4 minutes</span><span>${icon('shield')}No penalty for practising</span></div><button class="button primary" data-action="begin-challenge">Start the challenge ${icon('arrow')}</button>${state.challenge?`<p class="last-result">Best result: ${state.challenge.score}/6${state.challenge.score>=5?' · Learning badge earned':''}</p>`:''}</div></section><div class="info-note">${icon('book')}You can try this at any point. The eight missions and card lab help you prepare. This is a practice assessment, not a compliance attestation.</div>`;
}
function beginChallenge(){quiz={mode:'challenge',index:0,selected:null,results:[],questions:[0,1,2,3,4,6].map(i=>missions[i].questions[Math.floor(Math.random()*3)])};renderQuiz();}
function finishChallenge(){const score=quiz.results.filter(Boolean).length;const passed=score>=5;if(!state.challenge||score>=state.challenge.score)state.challenge={score,date:new Date().toISOString().slice(0,10)};save();quiz=null;
 main.innerHTML=`<section class="completion"><div class="completion-emblem ${passed?'':'muted'}">${icon(passed?'trophy':'book')}</div><span class="eyebrow">${passed?'LEARNING BADGE EARNED':'PRACTICE MAKES PROGRESS'}</span><h1>${passed?'Trust Champion.':'Keep building your instincts.'}</h1><p>You made ${score} of 6 correct decisions. ${passed?'You connected strong identity with everyday security.':'Review the explanations and try again when you are ready.'}</p><div class="big-result">${score}<span>/ 6</span></div><div class="button-row"><a class="button primary" href="#progress">See my progress ${icon('arrow')}</a><button class="button ghost" data-action="begin-challenge">Try a fresh challenge</button><a class="button ghost" href="#path">Review missions</a></div><p class="quiet-hint">Learning badge only · not an external certification</p></section>`;}
function renderLab(){
 const digital=lab.mode==='digital';const authenticated=lab.match&&(!digital||lab.site);const permitted=authenticated&&lab.active&&lab.rights;const title=permitted?'Access granted':!authenticated?'Authentication not completed':'Access denied by the system';
 const reason=!lab.match?'This fingerprint-first example cannot proceed without a successful local match.':digital&&!lab.site?'The lookalike relying party cannot use the legitimate service’s credential.':!lab.active?'The credential has been revoked in this system. A successful local match does not undo revocation.':!lab.rights?'The identity has no permission for this resource. Authentication and authorisation are separate.':'The credential is accepted and the access policy allows this request.';
 const controls=[['match','Fingerprint matches','Local user verification'],...(digital?[['site','Correct service / relying party','Try turning this off to model a lookalike site']]:[]),['active','Credential remains active','Turn off to model revocation in this system'],['rights','Permission is granted','Access to this specific service or door'],['verified','Identity checked at issuance','Turn off to see an identity-assurance gap']];
 main.innerHTML=pageHead('A SMALL LAB FOR BIG IDEAS','Follow the trust.','Change a condition. See what the card proves, and what the system still decides.')+`<div class="lab-tabs" role="group" aria-label="Simulation mode"><button data-action="lab-mode" data-mode="digital" class="${digital?'active':''}">${icon('laptop')}Digital sign-in · FIDO2</button><button data-action="lab-mode" data-mode="physical" class="${!digital?'active':''}">${icon('door')}Door access · DESFire</button></div><div class="lab-layout"><section class="lab-controls"><h2>Set the conditions</h2><p>Test one change at a time.</p>${controls.map(([id,label,desc])=>`<label class="toggle-row"><span><strong>${label}</strong><small>${desc}</small></span><input type="checkbox" data-lab="${id}" ${lab[id]?'checked':''}><span class="toggle-track" aria-hidden="true"></span></label>`).join('')}<button class="text-button" data-action="reset-lab">Restore a trusted setup ↺</button></section><section class="lab-stage"><span class="eyebrow">ILLUSTRATIVE SIMULATION · NO HARDWARE REQUIRED</span><div class="flow-grid"><div class="flow-node ${lab.match?'ok':'blocked'}"><div class="flow-icon">${icon('fingerprint')}</div><span>ON THE CARD</span><h3>Verify the user</h3><p>${lab.match?'Local match successful':'No successful match'}</p></div><div class="flow-node ${authenticated?'ok':'blocked'}"><div class="flow-icon">${icon(digital?'shield':'card')}</div><span>${digital?'FIDO2':'DESFIRE'}</span><h3>${digital?'Prove the credential':'Present the credential'}</h3><p>${digital?lab.site?'Correct relying party':'Lookalike relying party':'Door credential, not a passkey'}</p></div><div class="flow-node ${permitted?'ok':'blocked'}"><div class="flow-icon">${icon(digital?'laptop':'door')}</div><span>IN THE SYSTEM</span><h3>Check access policy</h3><p>${!lab.active?'Credential revoked':!lab.rights?'Permission missing':'Active & permitted'}</p></div></div><div class="lab-result ${permitted?'success':'warning'}" role="status"><div>${icon(permitted?'check':'lock')}<strong>${title}</strong></div><p>${reason}</p></div>${!lab.verified?`<div class="assurance-warning">${icon('radar')}<div><strong>Identity-assurance gap</strong><p>The technical checks can still succeed. They do not establish that the enrolled finger belongs to the person named on the account. Fix the issuance process.</p></div></div>`:''}<div class="stays"><span>${icon('lock')}Stays on the card<br><b>${digital?'Fingerprint template & private key':'Fingerprint template'}</b></span><span>${icon('arrow')}Used by the system<br><b>${digital?'Signature verified with public key':'Encoded door credential'}</b></span></div></section></div><div class="info-note">${icon('book')}Simplified, fingerprint-first flow. PIN behaviour, biometric gating, credential encoding and policy depend on the card profile and deployment. This lab does not read a card or collect biometric data.</div><div class="inline-sources">${['architecture','enrolment','standards','doors'].map(sourceLink).join('')}</div>`;
}
function renderGuide(){
 main.innerHTML=pageHead('PLAIN LANGUAGE. PRIMARY SOURCES.','Your security field guide.','A useful reference for customer conversations and the decisions you make every day.')+`<div class="guide-layout"><section class="glossary-panel"><div class="section-title"><h2>The essentials, decoded</h2></div><label class="search-label" for="glossary-search">Find a term<input id="glossary-search" type="search" placeholder="Try “passkey”, “identity” or “DESFire”…" autocomplete="off"></label><div id="glossary-list">${glossary.map(([t,d])=>`<details class="glossary-item"><summary>${t}<span>+</span></summary><p>${d}</p></details>`).join('')}</div><p class="empty-search" hidden>No matching terms. Try a broader search.</p></section><aside class="guide-note"><span class="eyebrow">THE PRODUCT STORY IN 20 SECONDS</span><h2>Bind access to the person holding the card.</h2><p>IDEX brings local fingerprint verification to supported card applications, including physical access, digital sign-in and biometric payment products.</p><p>The value depends on the whole chain: trusted issuance, the right card profile, secure integration and lifecycle control.</p><a class="button ghost" href="#lab">See it in the lab ${icon('arrow')}</a></aside></div><section class="source-section"><div class="section-title"><div><span class="eyebrow">CHECK THE EVIDENCE</span><h2>Sources behind the learning</h2></div><span class="section-hint">Reviewed 2 November 2026</span></div><div class="source-grid">${Object.entries(sources).map(([id,s])=>`<a class="source-card" href="${s.url}" target="_blank" rel="noopener noreferrer"><span>${icon('book')}<strong>${s.name}</strong>${icon('external')}</span><small>${s.date}</small></a>`).join('')}</div></section><section class="rollout-note"><span class="eyebrow">PILOT & ROLLOUT NOTES</span><h2>Before inviting every employee</h2><p>This pilot uses public product information and fictional learning scenarios. It is not an approved IDEX policy or formal certification.</p><ul><li>Have the product and security owners review claims against the card profiles IDEX actually supplies.</li><li>Add the verified internal reporting route, lost-card procedure, visitor process and approved data / AI tools.</li><li>Decide audience access, accessibility and language needs, then choose whether completion should be tracked in an LMS.</li></ul><p><strong>Privacy:</strong> answers, XP and the best challenge result are stored only in this browser. No name, email, fingerprint or central employee result is collected by this app. Hosting access logs are separate. Exporting a record downloads it to your device. Clearing browser storage removes local progress.</p><p>Quiz answer keys are included in this browser-based pilot. Results are self-directed learning records, not tamper-proof attestations.</p></section>`;
}
function renderProgress(){
 const done=completedCount();const champion=state.challenge?.score>=5;const mastered=Object.values(state.answers).filter(a=>a.mastered).length;const first=Object.values(state.answers).filter(a=>a.mastered&&a.attempts===1).length;
 main.innerHTML=pageHead('YOUR PROGRESS','Good habits add up.','A record of the security decisions you have practised in this browser.')+`<section class="progress-overview"><div class="progress-ring" style="--progress:${pct()}%"><span><b>${pct()}<small>%</small></b>path complete</span></div><div><span class="eyebrow">${rank().toUpperCase()}</span><h2>${done===8?'Every mission completed.':'Keep the momentum.'}</h2><p>${done} of 8 missions complete · ${mastered} of 24 decisions learned</p><div class="result-chips"><span>${icon('bolt')}${totalXP()} XP</span><span>${icon('check')}${first} correct on first attempt</span></div><a class="button primary" href="${done===8?'#challenge':'#mission/'+nextMission().id}">${done===8?'Take the final challenge':'Continue learning'}${icon('arrow')}</a></div></section><div class="section-title"><h2>Your learning badges</h2><span class="section-hint">Earned through practice</span></div><div class="badge-grid">${[[mastered>=1,'First good call','Learn your first decision.','bolt'],[missions.slice(0,6).every(completed),'Product insider','Complete all six product-focused missions.','card'],[done===8,'Security all-rounder','Complete all eight missions.','shield'],[champion,'Trust Champion','Get 5/6 or better in the final challenge.','trophy']].map(([earned,t,d,i])=>`<div class="badge-card ${earned?'earned':''}"><div>${icon(i)}</div><span class="eyebrow">${earned?'EARNED':'TO UNLOCK'}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><section class="progress-list"><div class="section-title"><h2>Your mission record</h2></div>${missions.map(m=>{const n=m.questions.filter(q=>state.answers[q.id]?.mastered).length;return `<a class="record-row" href="#mission/${m.id}"><span class="record-icon">${icon(m.icon)}</span><strong>${m.title}</strong><span>${n}/3 learned</span><span class="record-status ${n===3?'done':''}">${n===3?'Complete':n?'In progress':'Ready to start'}</span>${icon('arrow')}</a>`;}).join('')}</section><section class="record-tools"><div><h3>Your learning record belongs to you.</h3><p>Export a personal copy or clear this browser’s progress. No results are sent to an employer.</p></div><div class="button-row"><button class="button ghost" data-action="export">${icon('download')}Export record</button><button class="text-button" data-action="reset">Reset progress</button></div></section>`;
}
function exportRecord(){const record={title:'IDEX Security Academy — self-directed learning record',exportedAt:new Date().toISOString(),contentVersion:'1.0 / 2026-11-02',note:'Browser-local practice record; not verified identity, compliance attestation or external certification.',xp:totalXP(),missions:missions.map(m=>({title:m.title,complete:completed(m),learned:m.questions.filter(q=>state.answers[q.id]?.mastered).length})),bestChallenge:state.challenge};const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='idex-security-learning-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Learning record downloaded.');}
main.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='start'){quiz=null;const id=b.dataset.id;if(location.hash==='#mission/'+id){render();}else go('mission/'+id);}
 if(a==='answer')chooseAnswer(Number(b.dataset.index));
 if(a==='retry'){quiz.selected=null;renderQuiz();}
 if(a==='next'){quiz.index++;quiz.selected=null;renderQuiz();window.scrollTo({top:0,behavior:'instant'});}
 if(a==='begin-challenge')beginChallenge();
 if(a==='exit-challenge'){e.preventDefault();quiz=null;renderChallenge();}
 if(a==='lab-mode'){lab.mode=b.dataset.mode;renderLab();}
 if(a==='reset-lab'){lab={mode:lab.mode,match:true,site:true,active:true,rights:true,verified:true};renderLab();}
 if(a==='export')exportRecord();
 if(a==='reset')document.querySelector('#reset-dialog').showModal();
});
main.addEventListener('change',e=>{if(e.target.dataset.lab){const name=e.target.dataset.lab;lab[name]=e.target.checked;renderLab();main.querySelector(`[data-lab="${name}"]`)?.focus();}});
main.addEventListener('input',e=>{if(e.target.id==='glossary-search'){const term=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('.glossary-item').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(term);if(!el.hidden)count++;});document.querySelector('.empty-search').hidden=count>0;}});
document.querySelector('#cancel-reset').onclick=()=>document.querySelector('#reset-dialog').close();
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});};
document.querySelector('#confirm-reset').onclick=()=>{state={answers:{},challenge:null,lastMission:null};save();quiz=null;document.querySelector('#reset-dialog').close();render();toast('Progress reset. A fresh start.');};
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});});
render();
